const neighborsOf = ([x, y]: Cell): Cell[] =>
  [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );

const isLive = (cell: Cell, liveCells: Cell[]): boolean =>
  liveCells.some(([x, y]) => x === cell[0] && y === cell[1]);

const births = (liveCells: Cell[]): Cell[] =>
  liveCells
    .flatMap(neighborsOf)
    .filter((cell) => !isLive(cell, liveCells))
    .filter((cell) => countLiveNeighbors(cell, liveCells) === 3)
    .filter(
      (cell, index, candidates) =>
        index === candidates.findIndex((other) => isLive(cell, [other])),
    );

export const nextGeneration = (liveCells: Cell[]): Cell[] => [
  ...liveCells.filter((cell) => survives(cell, liveCells)),
  ...births(liveCells),
];
